CREATE TABLE "manual_deploy_attestations" (
	"deployment_id" text PRIMARY KEY NOT NULL,
	"org_id" text NOT NULL,
	"project_id" text NOT NULL,
	"app_id" text NOT NULL,
	"source_repo" text NOT NULL,
	"source_ref" text NOT NULL,
	"url" text NOT NULL,
	"surface_kind" text NOT NULL,
	"state" text DEFAULT 'pending_manual_confirmation' NOT NULL,
	"recorded_at" timestamp with time zone DEFAULT now() NOT NULL,
	"confirmed_at" timestamp with time zone,
	"confirmed_by" text,
	CONSTRAINT "manual_deploy_attestations_state_check" CHECK ("manual_deploy_attestations"."state" IN ('pending_manual_confirmation', 'confirmed')),
	CONSTRAINT "manual_deploy_attestations_surface_kind_check" CHECK ("manual_deploy_attestations"."surface_kind" IN ('web_url', 'download')),
	CONSTRAINT "manual_deploy_attestations_confirmation_shape_check" CHECK (("manual_deploy_attestations"."state" = 'pending_manual_confirmation' AND "manual_deploy_attestations"."confirmed_at" IS NULL AND "manual_deploy_attestations"."confirmed_by" IS NULL)
          OR ("manual_deploy_attestations"."state" = 'confirmed' AND "manual_deploy_attestations"."confirmed_at" IS NOT NULL AND "manual_deploy_attestations"."confirmed_by" IS NOT NULL))
);
