CREATE INDEX "manual_deploy_attestations_org_project" ON "manual_deploy_attestations" USING btree ("org_id","project_id");
-- ===========================================================================
-- Row-Level Security: deny-by-default org isolation on `manual_deploy_attestations`.
--
-- Direct-org_id (baseline §3a pattern, like post_merge_issue_claims / merge_queue
-- / candidates): the USING clause admits a row only when org_id matches the
-- request's `app.current_org_id` GUC (unset ⇒ ZERO rows, exactly like every
-- other tenant table), and the WITH CHECK keeps writes org-owned. A manual
-- deploy attestation is PRIVATE per-tenant delivery state — there is NO
-- cross-org catalogue tier (unlike templates). Idempotent via DROP POLICY IF
-- EXISTS. See db/src/schemaDeploy.ts.
-- ===========================================================================
ALTER TABLE manual_deploy_attestations ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS rls_org_isolation ON manual_deploy_attestations;--> statement-breakpoint
CREATE POLICY rls_org_isolation ON manual_deploy_attestations FOR ALL
  USING (org_id = current_setting('app.current_org_id', true))
  WITH CHECK (org_id = current_setting('app.current_org_id', true));
